// Places set by hand (c:manualLayout) of the plot area, the title and the
// legend, and slices pulled out of a pie. Every chart part is generated by
// code; text is measured by a stand-in.
//
// Excel is not at hand: what follows its known behaviour without having been
// compared with it is marked UNSURE.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { chartValues, layoutChart, type ChartItem, type ChartLayout } from '../src/layout/chart';
import type { Chart } from '../src/model/sheet/chart';
import { catAx, chartXml, fakeMeasure, group, legend, numLit, readChart, ser, strLit, title, valAx } from './chart-fixtures';

type Of<K extends ChartItem['kind']> = Extract<ChartItem, { kind: K }>;

function model(xml: string): Chart {
  const chart = readChart(xml);
  assert.ok(chart, 'the chart is read');
  return chart as Chart;
}

const lay = (xml: string, width = 500, height = 400): ChartLayout => {
  const chart = model(xml);
  return layoutChart(chart, chartValues(chart), width, height, fakeMeasure);
};
const items = <K extends ChartItem['kind']>(layout: ChartLayout, kind: K, role?: string): Of<K>[] => layout.items.filter((item) => item.kind === kind && (role === undefined || item.role === role)) as Of<K>[];
const near = (actual: number, expected: number, message: string, tolerance = 1e-6) => assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: ${actual} is not ${expected}`);

const manual = (inner: string) => `<c:layout><c:manualLayout>${inner}</c:manualLayout></c:layout>`;
const edge = (x: number | string, y: number | string, w?: number | string, h?: number | string, target = '') =>
  manual(`${target ? `<c:layoutTarget val="${target}"/>` : ''}<c:xMode val="edge"/><c:yMode val="edge"/><c:x val="${x}"/><c:y val="${y}"/>${w !== undefined ? `<c:w val="${w}"/>` : ''}${h !== undefined ? `<c:h val="${h}"/>` : ''}`);
const CATS = strLit(['Ocak', 'Şubat', 'Mart']);
const SERIES = ser(0, { tx: '<c:v>Satış</c:v>', cat: CATS, val: numLit([10, 20, 30]) }) + ser(1, { tx: '<c:v>Gider</c:v>', cat: CATS, val: numLit([5, 6, 7]) });
const BARS = group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', SERIES) + catAx() + valAx();
/** A chart whose plot area, title and legend may each have a place of their own. */
const chart = (plotLayout = '', titleLayout = '', legendLayout = '', plot = BARS, position = 'r') =>
  chartXml({ plot, head: title('Başlık').replace('<c:overlay', `${titleLayout}<c:overlay`), tail: legend(position, legendLayout) + '<c:plotVisOnly val="1"/>' }).replace('<c:plotArea><c:layout/>', `<c:plotArea>${plotLayout || '<c:layout/>'}`);

test('a plot area set by hand: the area of the series stands where the file says', () => {
  const auto = lay(chart());
  const layout = lay(chart(edge(0.2, 0.2, 0.6, 0.5, 'inner')));
  assert.deepEqual([layout.plot.x, layout.plot.y, layout.plot.width, layout.plot.height].map((value) => Math.round(value * 1000) / 1000), [100, 80, 300, 200]);
  assert.notDeepEqual(layout.plot, auto.plot);
  const bars = items(layout, 'rect', 'bar');
  assert.ok(bars.every((bar) => bar.x >= 100 && bar.x + bar.width <= 400 && bar.y >= 80 && bar.y + bar.height <= 280 + 1e-6), 'the columns stand in it');
  const ticks = items(layout, 'text', 'tick');
  assert.ok(ticks.length > 0 && ticks.every((item) => item.x < 100 && item.x > 80), 'the labels of the values stand beside it');
  assert.ok(items(layout, 'text', 'category').every((item) => item.y > 280 && item.y < 310), 'the labels of the categories below it');
});

test('a plot area set by hand with its labels ("outer", and where the file says nothing): the labels stand inside the place', () => {
  for (const target of ['outer', '']) {
    const layout = lay(chart(edge(0.2, 0.2, 0.6, 0.5, target)));
    const { plot } = layout;
    assert.ok(plot.x > 100 && plot.y >= 80 && plot.x + plot.width <= 400 + 1e-6 && plot.y + plot.height < 280, `${target || 'no target'}: the area of the series lies inside the place (${JSON.stringify(plot)})`);
    assert.ok(items(layout, 'text', 'tick').every((item) => item.x > 100), 'so do the labels of the values');
    assert.ok(items(layout, 'text', 'category').every((item) => item.y <= 280), 'and those of the categories');
  }
});

test('a place that is none, or that leaves no room for the labels, is not taken: the chart places the area itself', () => {
  const auto = lay(chart()).plot;
  const cases: [string, string][] = [
    ['no width', edge(0.2, 0.2, 0, 0.5, 'inner')],
    ['a negative height', edge(0.2, 0.2, 0.5, -0.5, 'inner')],
    ['beyond the frame', edge(0.6, 0.2, 0.6, 0.5, 'inner')],
    ['outside the frame', edge(1.5, 0.2, 0.2, 0.5, 'inner')],
    ['numbers that are none', edge('x', 0.2, 0.6, 0.5, 'inner')],
    ['no size at all', edge(0.2, 0.2, undefined, undefined, 'inner')],
    ['no room for the labels at the left', edge(0, 0.2, 0.6, 0.5, 'inner')],
    ['no room for the labels below', edge(0.2, 0.2, 0.6, 0.8, 'inner')],
    ['moved, not placed (factor)', manual('<c:layoutTarget val="inner"/><c:x val="0.2"/><c:y val="0.2"/><c:w val="0.6"/><c:h val="0.5"/>')],
    ['too small to draw in', edge(0.2, 0.2, 0.001, 0.001, 'inner')],
  ];
  for (const [name, layoutXml] of cases) assert.deepEqual(lay(chart(layoutXml)).plot, auto, name);
});

test('a pie in a plot area set by hand fills that place', () => {
  const pie = group('pieChart', '<c:varyColors val="1"/>', ser(0, { cat: CATS, val: numLit([1, 2, 3]) }), '', false);
  const layout = lay(chart(edge(0.5, 0.5, 0.4, 0.4, 'inner'), '', '', pie));
  const slice = items(layout, 'slice')[0];
  near(slice.cx, 350, 'the centre of the place, across');
  near(slice.cy, 280, 'and down');
  assert.ok(slice.radius <= 80 && slice.radius > 60, `as large as the place allows (${slice.radius})`);
});

test('a title set by hand: placed from the corner of the frame, or moved from where it would stand', () => {
  const auto = items(lay(chart()), 'text', 'title')[0];
  assert.deepEqual([auto.align, auto.x], ['center', 250]);
  const placed = items(lay(chart('', edge(0.1, 0.5))), 'text', 'title')[0];
  assert.deepEqual([placed.align, placed.x], ['left', 50], 'its left edge a tenth of the width in');
  near(placed.y - placed.font.size, 200, 'its top halfway down');
  const moved = items(lay(chart('', manual('<c:xMode val="factor"/><c:yMode val="factor"/><c:x val="0.1"/><c:y val="0.25"/>'))), 'text', 'title')[0];
  assert.deepEqual([moved.align, moved.x], ['center', 300], 'a tenth of the width to the right of the middle');
  near(moved.y, auto.y + 100, 'a quarter of the height down');
  const mixed = items(lay(chart('', manual('<c:xMode val="edge"/><c:x val="0.3"/><c:y val="0"/>'))), 'text', 'title')[0];
  assert.deepEqual([mixed.align, mixed.x, mixed.y], ['left', 150, auto.y], 'UNSURE: a direction without a mode is moved, by nothing here');
  // UNSURE: the room the title takes at the top stays where it was.
  assert.deepEqual(lay(chart('', edge(0.1, 0.5))).plot, lay(chart()).plot);
  for (const bad of [edge(1.5, 0.5), edge(0.1, -3), edge('x', 0.5), manual('<c:x val="7"/><c:y val="0"/>')]) {
    const item = items(lay(chart('', bad)), 'text', 'title')[0];
    assert.deepEqual([item.align, item.x, item.y], [auto.align, auto.x, auto.y], 'a place that is none: where the title stands by itself');
  }
  const far = items(lay(chart('', edge(0.99, 0.99))), 'text', 'title');
  for (const item of far) assert.ok(item.x >= 0 && item.x <= 500 && item.y <= 400, 'a title at the edge stays in the frame');
});

test('a legend set by hand stands in its place; the plot area keeps the room the legend would take by itself', () => {
  const auto = lay(chart());
  const layout = lay(chart('', '', edge(0.1, 0.6, 0.3, 0.3)));
  const entries = items(layout, 'text', 'legend');
  assert.deepEqual(entries.map((item) => item.text), ['Satış', 'Gider']);
  assert.ok(entries.every((item) => item.x >= 50 && item.x <= 200 && item.y >= 240 && item.y <= 360), `the entries stand in the place (${entries.map((item) => `${item.x},${item.y}`).join(' ')})`);
  assert.ok(entries[1].y > entries[0].y, 'one below the other, as the legend of a side does');
  const swatches = items(layout, 'rect', 'swatch');
  assert.ok(swatches.length === 2 && swatches.every((item) => item.x >= 50 && item.x < 200), 'with their keys');
  // UNSURE: the plot area is as it is with the legend where it stands by itself.
  assert.deepEqual(layout.plot, auto.plot);
  const row = lay(chart('', '', edge(0.1, 0.9, 0.8, 0.08), BARS, 'b'));
  const across = items(row, 'text', 'legend');
  assert.ok(across.length === 2 && across[0].y === across[1].y && across[1].x > across[0].x && across.every((item) => item.x >= 50 && item.y >= 360), 'a legend of the top or the bottom lists its entries side by side');
  const narrow = lay(chart('', '', edge(0.1, 0.6, 0.08, 0.3)));
  assert.ok(items(narrow, 'text', 'legend').every((item) => item.text.endsWith('…')), 'names are cut to the width of the place');
  const low = lay(chart('', '', edge(0.1, 0.6, 0.3, 0.05)));
  assert.equal(items(low, 'text', 'legend').length, 1, 'and entries that do not fit its height are left out');
  const natural = lay(chart('', '', edge(0.1, 0.6)));
  assert.deepEqual(items(natural, 'text', 'legend').map((item) => item.text), ['Satış', 'Gider'], 'without a size: as large as it is');
  for (const bad of [edge(1.2, 0.5, 0.3, 0.3), edge(0.1, 0.6, 3, 0.3), manual('<c:x val="0.1"/><c:y val="0.6"/>')]) {
    assert.deepEqual(items(lay(chart('', '', bad)), 'text', 'legend'), items(auto, 'text', 'legend'), 'a place that is none: where the legend stands by itself');
  }
});

// ------------------------------------------------------------------ explosion

const pie = (props: string, name = 'pieChart', tail = '') => chartXml({ plot: group(name, '<c:varyColors val="1"/>', ser(0, { cat: strLit(['a', 'b', 'c', 'd']), val: numLit([1, 1, 1, 1]), props }), tail, false) });

test('slices pulled out of a pie: each moved along its middle, the pie made smaller to keep them in the frame', () => {
  const plain = lay(pie(''));
  const whole = items(plain, 'slice')[0].radius;
  const centre = { x: items(plain, 'slice')[0].cx, y: items(plain, 'slice')[0].cy };
  const layout = lay(pie('<c:explosion val="25"/>'));
  const slices = items(layout, 'slice');
  near(slices[0].radius, whole / 1.25, 'the radius leaves room for a quarter of itself');
  slices.forEach((slice, i) => {
    const middle = (slice.start + slice.end) / 2;
    near(slice.cx, centre.x + Math.cos(middle) * slice.radius * 0.25, `slice ${i} is moved a quarter of the radius, across`);
    near(slice.cy, centre.y + Math.sin(middle) * slice.radius * 0.25, `slice ${i}, down`);
    assert.ok(slice.cx - slice.radius >= -1 && slice.cx + slice.radius <= layout.width + 1 && slice.cy - slice.radius >= -1 && slice.cy + slice.radius <= layout.height + 1, `slice ${i} stays in the frame`);
  });
});

test('a single slice pulled out; a point that says zero stays where the others move', () => {
  const one = items(lay(pie('<c:dPt><c:idx val="2"/><c:explosion val="50"/></c:dPt>')), 'slice');
  assert.deepEqual([one[0].cx, one[1].cx, one[3].cx], [one[0].cx, one[0].cx, one[0].cx], 'the others share a centre');
  const middle = (one[2].start + one[2].end) / 2;
  near(one[2].cx - one[0].cx, Math.cos(middle) * one[2].radius * 0.5, 'the third is moved half a radius');
  near(one[2].cy - one[0].cy, Math.sin(middle) * one[2].radius * 0.5, 'along its middle');
  const stay = items(lay(pie('<c:explosion val="30"/><c:dPt><c:idx val="1"/><c:explosion val="0"/></c:dPt>')), 'slice');
  const plain = items(lay(pie('')), 'slice')[0];
  assert.deepEqual([stay[1].cx, stay[1].cy], [plain.cx, plain.cy], 'the second stays at the centre');
  assert.notDeepEqual([stay[0].cx, stay[0].cy], [plain.cx, plain.cy], 'the first is moved');
});

test('pulled out as far as a file may say: the pie is small, and nothing leaves the frame', () => {
  const layout = lay(pie('<c:explosion val="999"/>'));
  for (const slice of items(layout, 'slice')) {
    assert.ok(slice.radius > 0 && Number.isFinite(slice.cx) && Number.isFinite(slice.cy), 'a slice that can be drawn');
    assert.ok(slice.cx - slice.radius >= -1 && slice.cx + slice.radius <= layout.width + 1 && slice.cy - slice.radius >= -1 && slice.cy + slice.radius <= layout.height + 1, 'in the frame');
  }
  const labelled = lay(pie('<c:explosion val="50"/><c:dLbls><c:showVal val="1"/><c:dLblPos val="ctr"/></c:dLbls>'));
  const slice = items(labelled, 'slice')[0];
  const label = items(labelled, 'text', 'label')[0];
  const middle = (slice.start + slice.end) / 2;
  near(label.x, slice.cx + Math.cos(middle) * slice.radius * 0.55, 'the label of a slice moves with it', 0.5);
  const ring = items(lay(pie('<c:explosion val="20"/>', 'doughnutChart', '<c:holeSize val="50"/>')), 'slice');
  assert.ok(ring.some((item) => item.cx !== ring[0].cx || item.cy !== ring[0].cy), 'the slices of a doughnut are pulled out too');
});
